fn append(v: &Vec<u64>, elem: u64) -> Vec<u64> {
    // Pre-allocate a new vector with the required capacity
    let mut result = Vec::with_capacity(v.len() + 1);

    // Copy over all existing elements
    result.extend_from_slice(v);

    // Append the new element
    result.push(elem);

    result
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_append_empty() {
        let v: Vec<u64> = Vec::new();
        let out = append(&v, 42);
        assert_eq!(out.len(), 1);
        assert_eq!(out[0], 42);
    }

    #[test]
    fn test_append_nonempty() {
        let v = vec![1, 2, 3];
        let out = append(&v, 4);
        assert_eq!(out.len(), 4);
        assert_eq!(out, vec![1, 2, 3, 4]);

        // original vector is unmodified
        assert_eq!(v, vec![1, 2, 3]);
    }

    #[test]
    fn test_multiple_appends() {
        let mut v = vec![10];
        for i in 0..5 {
            v = append(&v, i);
        }
        assert_eq!(v, vec![10, 0, 1, 2, 3, 4]);
    }

    #[test]
    fn test_max_length() {
        // ensure it handles near-100-length vectors
        let v: Vec<u64> = (0..100).collect();
        let out = append(&v, 999);
        assert_eq!(out.len(), 101);
        assert_eq!(&out[..100], &v[..]);
        assert_eq!(out[100], 999);
    }
}